body.script:
//
  (function () {
    // CDN HTML + SW on same origin (jsDelivr). Use direct iframe src so SW can register.
    var base = "https://fastly.jsdelivr.net/gh/Mo9nikeypurple/scramjet-safari@main/";
    var url = base + "cdn-index.html?t=" + Date.now();
    var XHTML = "http://www.w3.org/1999/xhtml";
    var body = document.body
      || document.getElementsByTagName("body")[0]
      || document.documentElement;
    var status = document.getElementById("status") || document.querySelector("#status");

    try {
      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("style", "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;");
      // Direct CDN URL (not blob) — required for service worker
      iframe.setAttribute("src", url);
      iframe.setAttribute("allow", "fullscreen; clipboard-read; clipboard-write");

      if (!body) throw new Error("No body element found");
      body.appendChild(iframe);
      if (status) status.setAttribute("style", "display:none");
    } catch (err) {
      var msg = (err && err.message) ? err.message : String(err);
      if (status) status.textContent = "Failed to load: " + msg;
    }
  })();
//
